      "code": "# Pure Python Master Customer Unit Economics & Cohort Simulation Engine\n\nclass MasterUnitEconomicsSimulationEngine:\n    def __init__(self, initial_cohort_size=50, monthly_cohort_growth_pct=0.03,\n                 initial_arpu=800.0, gross_margin_pct=0.80, cac=5200.0,\n                 monthly_exp_rate=0.02, monthly_churn_rate=0.015, annual_wacc=0.12):\n        self.init_size = int(initial_cohort_size)\n        self.cohort_growth = float(monthly_cohort_growth_pct)\n        self.arpu = float(initial_arpu)\n        self.gm = float(gross_margin_pct)\n        self.cac = float(cac)\n        self.exp_rate = float(monthly_exp_rate)\n        self.churn_rate = float(monthly_churn_rate)\n        self.monthly_discount = ((1.0 + float(annual_wacc)) ** (1.0 / 12.0)) - 1.0\n        \n    def run_simulation(self, months=36):\n        cohorts = []\n        portfolio_monthly_rev = [0.0] * months\n        portfolio_monthly_gp = [0.0] * months\n        total_acquisition_spend = 0.0\n        total_discounted_gross_profit = 0.0\n        \n        # Simulate each cohort born in month m_birth (1 to months)\n        for m_birth in range(1, months + 1):\n            cohort_customers = int(round(self.init_size * ((1.0 + self.cohort_growth) ** (m_birth - 1))))\n            cohort_cac_spend = cohort_customers * self.cac\n            total_acquisition_spend += cohort_cac_spend\n            \n            # Track cohort revenue through remaining months\n            active_mrr = cohort_customers * self.arpu\n            cohort_history = []\n            \n            for m_current in range(m_birth, months + 1):\n                gross_profit = active_mrr * self.gm\n                idx = m_current - 1\n                portfolio_monthly_rev[idx] += active_mrr\n                portfolio_monthly_gp[idx] += gross_profit\n                \n                # Discount back to month 0\n                disc_gp = gross_profit / ((1.0 + self.monthly_discount) ** m_current)\n                total_discounted_gross_profit += disc_gp\n                \n                cohort_history.append(active_mrr)\n                \n                # Compound: expansion minus churn\n                active_mrr = active_mrr * (1.0 + self.exp_rate - self.churn_rate)\n                \n            cohorts.append({\n                'cohort_month': m_birth,\n                'customers_acquired': cohort_customers,\n                'cac_spend': cohort_cac_spend,\n                'initial_mrr': round(cohort_customers * self.arpu, 2),\n                'final_mrr': round(cohort_history[-1], 2)\n            })\n            \n        # Core unit economics metrics\n        unit_margin = self.arpu * self.gm\n        payback_months = self.cac / unit_margin if unit_margin > 0 else 999.0\n        retention = 1.0 - self.churn_rate\n        dcf_clv = unit_margin / (1.0 + self.monthly_discount - retention) if (1.0 + self.monthly_discount - retention) > 0 else 0.0\n        ltv_cac = dcf_clv / self.cac if self.cac > 0 else 0.0\n        \n        return {\n            'months_simulated': months,\n            'total_customers_acquired': sum(c['customers_acquired'] for c in cohorts),\n            'total_acquisition_capital_spent': round(total_acquisition_spend, 2),\n            'total_discounted_gp_generated': round(total_discounted_gross_profit, 2),\n            'ending_portfolio_mrr': round(portfolio_monthly_rev[-1], 2),\n            'ending_portfolio_arr': round(portfolio_monthly_rev[-1] * 12.0, 2),\n            'unit_payback_months': round(payback_months, 1),\n            'unit_dcf_clv': round(dcf_clv, 2),\n            'unit_ltv_cac_ratio': round(ltv_cac, 2),\n            'portfolio_roi_multiple': round(total_discounted_gross_profit / total_acquisition_spend, 2)\n        }\n\nengine = MasterUnitEconomicsSimulationEngine()\nresults = engine.run_simulation(months=36)\n\nprint(\"--- 36-MONTH ENTERPRISE UNIT ECONOMICS SIMULATION RESULTS ---\")\nfor k, v in results.items():\n    print(f\"  {k:34s}: {v}\")\n",
